  role: Schema.Literal("tool"),
  type: Schema.Literal("tool-result"),
  toolCallId: BoundedLabelSchema,
  toolName: Schema.NonEmptyString.check(Schema.isMaxLength(MAX_LABEL_LENGTH)),
  output: Schema.Json,
  isError: Schema.Boolean,
});

